// Lees huidige teller en jaar uit de vorige node of database
const body = $('Webhook: Factuur aanmaken').first().json.body;
const customer = $input.first().json;

// Haal instellingen op uit database (zie SQLite node hiervoor)
// Hier gesimuleerd — in productie via extra SQLite node
const prefix = 'NW';
const currentYear = new Date().getFullYear().toString();

// Verhoog teller (gesimuleerd; in productie via UPDATE in SQLite)
let counter = parseInt($node['SQLite: Instellingen ophalen']?.json?.invoice_counter || '0') + 1;

// Reset bij jaarwisseling
const storedYear = $node['SQLite: Instellingen ophalen']?.json?.invoice_year || currentYear;
if (storedYear !== currentYear) {
  counter = 1;
}

// Formatteer als NW-YYYY-NNNN
const paddedCounter = String(counter).padStart(4, '0');
const invoiceNumber = `${prefix}-${currentYear}-${paddedCounter}`;

return [{
  json: {
    invoice_number: invoiceNumber,
    counter: counter,
    year: currentYear,
    customer: customer,
    body: body
  }
}];

const data = $input.first().json;
const body = data.body;
const today = new Date().toISOString().split('T')[0];
const paymentDays = 30;
const dueDate = new Date(Date.now() + paymentDays * 86400000).toISOString().split('T')[0];

// Bereken per regel
const regels = [];
let subtotal = 0;
let btwTotaal = 0;

for (let i = 1; i <= 3; i++) {
  const omschrijving = body[`omschrijving${i}`] || '';
  if (!omschrijving) continue;

  const aantal = parseFloat(body[`aantal${i}`] || 1);
  const prijs = parseFloat(body[`prijs${i}`] || 0);
  const btwPct = parseFloat(body[`btw${i}`] || 21);

  const lineExcl = Math.round(aantal * prijs * 100) / 100;
  const btwBedrag = Math.round(lineExcl * btwPct / 100 * 100) / 100;
  const lineTotal = Math.round((lineExcl + btwBedrag) * 100) / 100;

  subtotal += lineExcl;
  btwTotaal += btwBedrag;

  regels.push({
    omschrijving,
    aantal,
    prijs,
    btw_percentage: btwPct,
    btw_bedrag: btwBedrag,
    regel_totaal: lineTotal
  });
}

subtotal = Math.round(subtotal * 100) / 100;
btwTotaal = Math.round(btwTotaal * 100) / 100;
const total = Math.round((subtotal + btwTotaal) * 100) / 100;

return [{
  json: {
    ...data,
    invoice_date: today,
    due_date: dueDate,
    regels,
    subtotal,
    btw_total: btwTotaal,
    total
  }
}];

